    "deathYear": 1965,
    "shortBio": "عاش الزبيري فترة حرجة من تاريخ اليمن، وهي فترة المملكة المتوكلية اليمنية (1918م - 1962م)، التي كثرت فيها الصِّراعات والثورات، وحينما شبت ثورة الدستور عام 1948م في اليمن عاد من عدن إلى صنعاء وزيراً للمعارف، وعندما فشلت طورد، ورفضت الدول العربية استضافته فاتجه إلى باكستان. وحينما شبت ثورة 26 سبتمبر عام 1962م في اليمن عاد وزيراً للتربية والتعليم في صنعاء.",
