    "id": "catalog-q12189231",
    "slug": "q12189231",
    "fullName": "عبد الرحمن باعباد",
    "knownFor": "داعية إسلامي يمني",
    "field": "العلم والتعليم",
    "governorateId": "",
    "governorateName": "",
    "era": "تاريخية",
    "birthYear": 1973,
    "deathYear": 2018,
    "shortBio": "عبد الرحمن باعباد (1393 - 1440 هـ): داعية إسلامي وشيخ تربية وعميد رباط الإسعاد للدراسات الإسلامية ب مدينة الغرفة في حضرموت اليمنية، كما كان إمام وخطيب الجامع الكبير بالغرفة. وكان يقيم يومياً وأسبوعياً الدروس العلمية والمجالس العامة ويشرف على حلقات التحفيظ والدروس الشرعية بالمساجد. كما شارك في العديد من الندوات والمؤتمرات واللقاءات الإذاعية والتلفزيونية داخل اليمن وخارجها. اشتهر عنه إصلاح ذات البين في كثير من القضايا والأحداث الاجتماعية في حضرموت وذلك بعد إسهاماته في تأسيس مؤتمر حضرموت الجامع و حلف قبائل حضرموت قبل ذلك. وله مساعيه في خدمة المجتمع وتطوير الواقع الحضرمي من خلال ترؤسه ل مؤسسة الوسط للتنمية بمدينة سيئون.",
