    "shortBio": "سالم بن عبد الله الشاطري (1359 - 1439 هـ) فقيه شافعي وداعية إسلامي ومدرس ب رباط تريم للعلوم الدينية والعربية ب حضرموت. يعتبر من أهم علماء الشافعية في اليمن بل وفي العالم الإسلامي، ومن أبرز رجال الدين ب مدينة تريم إذ يلقب بـ«سلطان العلماء» لما يتميز به من غزارة في العلم ولتصدره العديد من المجالس العلمية في تريم، وكان المدير العام ل رباط تريم العلمي أحد أبرز دور العلم الشرعي بالمدينة. تخرج على يده الآلاف من العلماء والدعاة والمصلحين الذين كان لهم دور في الوعي والثقافة ونشر العقيدة الإسلامية حول العالم.",
