    "shortBio": "ولد عام في يناير 1965م ونشأ في مدينة صنعاء. درس مراحل التعليم النّظاميّ، ثم التحق بجامعة صنعاء، فحصل عام 1404هـ/1984م على بكالوريوس في التجارة. عيّن عام 1405هـ/1985م موظّفًا في مكتب الطّيران اليمني، وتدرّج في عمله الوظيفي حتى أصبح مدير مبيعات. وفي المجال الرياضي بدأ حياته عام 1400هـ/1980م حارسًا لمرمى فريق (الزُّهرة) أحد أندية العاصمة صنعاء، ثم اختير حارسًا للمنتخب اليمني، ثم أعلن اعتزاله، وعيّن مدرّبًا لنادي الزّهرة، ثم مدرّبًا لنادي الوحدة، ثم مساعداً لمدرب المنتخب اليمني.",
