    "shortBio": "أبو بكر سالم بلفقيه (17 مارس 1939 - 10 ديسمبر 2017) مغني و أديب و شاعر و ملحن من أشهر الفنانين العرب على الساحة الخليجية والعربية ويلقب بـ«أبو الغناء الخليجي». أجاد ألوان الغناء العربية المختلفة؛ فقد برز في الغناء الحضرمي الذي بدأ يمارسه منذ بداياته الفنية، وأيضاً الغناء الخليجي، كما قدّم عدد من الأغاني باللون الصنعاني منها: (قال المعنى لمه)، و (مسكين يا ناس)، و (يا ليل هل أشكو)، و (وامغرد)، و (بات ساجي الطرف)، و (أحبة ربى صنعاء)، و (رسولي قوم)، و (مجروح) و (أصيل والله أصيل)، بالإضافة إلى القصائد الفصيحة لأبي القاسم الشابي، وأيضًا الحفلات الغنائية في مهرجانات الأغنية العربية المتعددة.",
