    "shortBio": "عبد الله البردوني شاعر وناقد ومؤرخ أدبي يمني، وُلد في قرية البردون بمحافظة ذمار سنة 1929 وتوفي في صنعاء في 30 أغسطس 1999. فقد بصره في طفولته، وتلقى تعليمه في ذمار وصنعاء، ثم جمع بين كتابة الشعر والدراسات الأدبية والعمل الثقافي والإذاعي. ولد البردوني عام 1929 في قرية البرَدُّون في محافظة ذمار وأصيب بالجدري الذي أدى إلى فقدانه بصره وهو في الخامسة من عمره، ولُقب على أثر ذلك بمعرّي اليمن نسبة إلى الشاعر الأعمى أبي العلاء المعري تلقى تعليمه الأولي في قريته قبل أن ينتقل مغتربًا عن أسرته إلى مدينة ذمار ويلتحق بالمدرسة الشمسية الزيدية المذهب.",
