    "era": "تاريخية",
    "birthYear": 1952,
    "deathYear": 2020,
    "shortBio": "حسن أحمد اللوزي (1952-2020) هو سياسي وشاعر وكاتب مسرحي يمني. وتلقى تعليمه الابتدائي والإعدادي في مسقط رأسه. ثم رحل إلى مصر فدرس الثانوية الأزهرية في القاهرة، والتحق بجامعة الأزهر، كلية الشريعة والقانون. بعد عودته إلى الوطن تقلد العديد من المناصب أهمها وزيراً للإعلام والثقافة في الجمهورية العربية اليمنية. وفي 1994 عين سفيراً في المملكة الأردنية الهاشمية. وفي 2006 أصبح وزير الإعلام مرةً أخرى. أسس صحيفة الميثاق ومجلة معين وترأس تحريرهما. وهو عضو في اتحاد الأدباء والكتاب اليمنيين وعضو في اتحاد أدباء وكتاب العرب.",
