    "shortBio": "إبراهيم بن عمر بن عقيل بن يحيى (1327 - 1415 هـ) فقيه ومحدث سني صوفي يمني، ومفتي الديار التعزية وشيخ علمائها. كان إمام وخطيب جامع المظفر بتعز، وله الكثير من الإسهامات والأنشطة العلمية في المساجد والمدارس والبحوث والندوات والمجلات. تولى العديد من المناصب الهامة في اليمن حيث كان مقربًا من السلطة. وكان من ضمن المبتعثين إلى دولة العراق لدراسة العلوم العسكرية سنة 1355 هـ.",
