    "birthYear": 1946,
    "deathYear": 2022,
    "shortBio": "أبو بكر العدني ابن علي المشهور (1366 - 1443 هـ) فقيه وأديب ومتصوف ومفكّر وداعية إسلامي يمني. ينتمي إلى أسرة السادة آل باعلوي الحضارمة. ويعتبر من أشهر أعلام مدرسة التصوف العلوية الحضرمية في التاريخ المعاصر. أنشأ عشرات المعاهد التربوية التعليمية في اليمن، ومراكز للدراسات والأبحاث العلمية. وله العديد من المؤلفات والمنظومات والأطروحات الفكرية في مختلف المجالات. وهو الموجه العام لأربطة التربية الإسلامية ومراكزها التعليمية والمهنية في الجمهورية اليمنية، ورئيس جامعة الوسطية الشرعية للعلوم الإسلامية والإنسانية.",
