    "shortBio": "عيدروس قاسم الزبيدي شخصية سياسية وعسكرية يمنية من محافظة الضالع، وُلد سنة 1967. تولى منصب محافظ عدن من ديسمبر 2015 إلى أبريل 2017، ثم برز في قيادة المجلس الانتقالي الجنوبي الذي أُعلن تأسيسه سنة 2017. بعد تحرير الضالع توجه عيدروس قواته معززين بالأسلحة الثقيلة وراجمات الصواريخ إلى منطقة النخيلة في مديرية المسيمير محافظة لحج لقطع طريق الإمداد الرابط بين كرش ومثلث العند.",
