    "shortBio": "محمد علي عثمان (1904 - 1973) سياسي يمني معارض للحكم الملكي في اليمن، وقد تم تعيينه كأول رئيس لمجلس السيادة لليمن بعد الثورة. وفي الفترة التي تلت إزاحة الرئيس عبد الله السلال عن طريق الانقلاب، تم تشكيل المجلس الجمهوري الذي شغل الشيخ محمد علي عثمان إلى جانب عبد الرحمن الأرياني وأحمد محمد نعمان وحسن العمري عضويته. وبعد المصالحة اليمنية بين الجمهوريين والملكيين وانتخاب مجلس شورى، تم إجراء انتخابات لأعضاء المجلس الجمهوري حيث فاز الشيخ محمد علي عثمان بعضوية المجلس، وظل فيه إلى أن اغتيل في 30 مايو 1973م.",
