    "shortBio": "ولد محمد قاسم الأخفش سنة 1946 فيمنطقة الروضة شمال صنعاء، ونشأ فيأسرة فنية يقود تقاليدها والده الفنان قاسم الأخفش، الذي جمع التعليم وحفظ القرآن بالغناء والتلحين. بدأ محمد الغناء قبل العاشرة، فتلقى معرفة مباشرة بطريقة التعامل مع العود والنص والألحان الصنعانية. كان والده معلماً لفنانين آخرين أيضاً، ومنهم أحمد السنيدار ومحمد الخميسي، ولذلك تشكلت بداياته فيبيت ينقل الخبرة بين الأجيال، لا فيتعلم فردي بعيد عن المحيط الموسيقي.",
    "biographyText": "ولد محمد قاسم الأخفش سنة 1946 فيمنطقة الروضة شمال صنعاء، ونشأ فيأسرة فنية يقود تقاليدها والده الفنان قاسم الأخفش، الذي جمع التعليم وحفظ القرآن بالغناء والتلحين. بدأ محمد الغناء قبل العاشرة، فتلقى معرفة مباشرة بطريقة التعامل مع العود والنص والألحان الصنعانية. كان والده معلماً لفنانين آخرين أيضاً، ومنهم أحمد السنيدار ومحمد الخميسي، ولذلك تشكلت بداياته فيبيت ينقل الخبرة بين الأجيال، لا فيتعلم فردي بعيد عن المحيط الموسيقي.",
