    "biographyText": "يحيى عمر اليافعي، المشهور بأبي معجب، شاعر غنائي وملحن يمني من مشألة فييافع، ارتبط اسمه ببيت الجمالي وبالقصيدة التي غناها فنانو اليمن والخليج عبر أجيال. عاش قبل العصر الحديث وتداخلت سيرة تنقلاته مع الروايات الشعبية، فلا يعتمد الملف سنة ميلاد أو وفاة من دون حسم. يميز البحث المحقق بين ما يستفاد من قصائده وشواهدها وبين الأخبار التي بنتها الذاكرة حول شخصيته، مع بقاء أصله اليافعي وانتشار شعره من أوضح عناصر سيرته.",
