    "id": "catalog-ibrahim-al-hadhrani",
    "slug": "ibrahim-al-hadhrani",
    "fullName": "إبراهيم أحمد الحضراني",
    "knownFor": "من رواد الشعر اليمني الحديث، جمع بين الفصحى والقصيدة الغنائية ومن مؤسسي اتحاد الأدباء والكتاب اليمنيين.",
    "field": "الأدب والشعر",
    "governorateId": "YE20",
    "governorateName": "ذمار",
    "era": "معاصرة",
    "birthYear": null,
    "deathYear": 2007,
    "shortBio": "النشأة والتكوين",
    "biographyText": "النشأة والتكوين\n\nينتمي إبراهيم أحمد الحضراني إلى جيل الشعراء الذي ربط التعليم التقليدي بتحولات اليمن الثقافية في القرن العشرين. نشأ في منطقة آنس بمحافظة ذمار، وتلقى دروسه الأولى في محيطه الأسري قبل انتقاله إلى مدينة ذمار. تختلف المراجع في سنة مولده بين 1919 و1920؛ لذلك لا تثبت هذه السيرة سنة قاطعة. شملت قراءاته الأدب العربي والنحو والبلاغة والتاريخ والعلوم الشرعية، ثم امتدت إلى الأدب العالمي المتاح بالعربية.\n\nتعز والوسط الأدبي\n\nانتقل الحضراني إلى تعز في الفترة التي كان فيها أحمد حميد الدين وليًا للعهد، والتقى في مجالسها عددًا من أدباء اليمن. أسهمت المساجلات واللقاءات بين شعراء ذلك الجيل في تداول القصائد وصقل التجربة خارج نظام النشر المحدود آنذاك. جمع في شعره بين البناء الفصيح واللغة الغنائية القريبة من التعبير اليومي، وشارك لاحقًا في تأسيس اتحاد الأدباء والكتاب اليمنيين، بما وصل تجربته الفردية بالعمل الثقافي المؤسسي.\n\nالدواوين وحفظ القصائد\n\nتداول القراء شعر الحضراني قبل اكتمال جمعه في دواوين. وتولى صديقه الشاعر أحمد محمد الشامي جمع مجموعة من قصائده في «القطوف الدواني»، وهو عمل ارتبط بالتعريف بمسيرته خارج محيط الجلسات والرواية الشفوية. وفي مرحلة لاحقة عمل علوان مهدي الجيلاني على تحقيق ديوانه والبحث عما تفرق من شعره؛ فأصدرت وزارة الثقافة اليمنية هذه المادة سنة 2006 وأقامت له مناسبة تكريمية.\n\nالحضور الثقافي والرحيل\n\nشغل الحضراني مهام ثقافية في الوفد اليمني لدى الجامعة العربية وفي السفارة اليمنية بالكويت ووزارة الثقافة بحسب سيرته الأدبية. وكتب عن تجربته عبد الله البردوني وعبد العزيز المقالح وأحمد الشامي وغيرهم، وخصصت مجلة «الحكمة» مساحة للاحتفاء به. توفي بصنعاء في نوفمبر 2007 ودُفن في مقبرة خزيمة. وتظل سيرته مرتبطة بتاريخ القصيدة الحديثة وبجهود جمع شعر جيل كانت وسائل نشره وتوثيقه محدودة.",
