    "id": "catalog-ismail-ali-al-akwa",
    "slug": "ismail-ali-al-akwa",
    "fullName": "إسماعيل بن علي الأكوع",
    "knownFor": "مؤرخ اليمن وصاحب «هجر العلم ومعاقله في اليمن» ومؤسس الهيئة العامة للآثار ودور الكتب.",
    "field": "التراث والتاريخ",
    "governorateId": "YE20",
    "governorateName": "ذمار",
    "era": "معاصرة",
    "birthYear": 1920,
    "deathYear": 2008,
    "shortBio": "ذمار وبدايات التكوين",
    "biographyText": "ذمار وبدايات التكوين\n\nولد إسماعيل بن علي الأكوع في ذمار سنة 1920 في أسرة اشتغل أفرادها بالقضاء والعلم. تلقى تعليمه في المعلامة والمكتب ثم درس العلوم الشرعية والعربية على والده علي بن حسين الأكوع وعلى علماء من محيطه، وكان أخوه الأكبر محمد من شيوخه. شملت دراسته القرآن والحديث والفقه وأصوله والنحو والبيان. وامتزج هذا التكوين بالرحلة ومجالسة العلماء، ثم توسع إلى الاهتمام بالبلدان والأنساب والمخطوطات.\n\nالحركة الوطنية والدبلوماسية\n\nانخرط الأكوع في الحركة الوطنية وتعرض للسجن والتنقل خارج اليمن، ثم شغل مهام في السلك الدبلوماسي والخارجية بعد عودته. عمل في المفوضية اليمنية بموسكو، وفي سفارة اليمن بالقاهرة، وتولى مواقع بوزارة الخارجية ثم وزارة الإعلام. وبعد استقالة الحكومة سنة 1969 اتجه إلى مشروع مؤسسي لحفظ الآثار والكتب، فصار العمل على ذاكرة البلاد محور نشاطه المهني والعلمي في العقود التالية.\n\nحفظ الآثار والبحث الميداني\n\nأسس الهيئة العامة للآثار ودور الكتب وتولى رئاستها لأكثر من عشرين عامًا حتى 1990. ربط هذا العمل جمع المخطوطات والتعريف بالآثار بالبحث في التاريخ المحلي؛ فكان يتنقل بين القرى والمدن ويلتقي العلماء ويجمع شهاداتهم وأسماء المواضع. وتظهر هذه الطريقة خصوصًا في «هجر العلم ومعاقله في اليمن»، حيث لا تقتصر المادة على سرد الأسماء، بل تربط العلماء بمراكز التعليم والمساجد والقرى التي احتضنت نشاطهم.\n\nالمؤلفات والحضور العلمي\n\nمن مؤلفاته «الأمثال اليمانية» و«المدارس الإسلامية في اليمن» و«الدولة الرسولية في اليمن»، وله تحقيقات وتعليقات في الجغرافيا والتراجم. تناول في هذه الأعمال التراث الشفوي ونظام التعليم والدول والمواقع، كما شارك في مجامع وهيئات علمية عربية وإسلامية. توفي بصنعاء في أكتوبر 2008. وبقيت كتبه مراجع لدراسة تاريخ التعليم والعمران والبلدان، ووسيلة لحفظ أسماء ومواد كان بعضها معرضًا للاندثار.",
