    "deathYear": 1998,
    "shortBio": "الأسرة والتعليم",
    "biographyText": "الأسرة والتعليم\n\nولد محمد بن علي الأكوع في ذمار سنة 1903، ونشأ في أسرة علمية أخذ فيها عن والده وعن عدد من علماء المدينة. اشتغل بتدريس العلوم الشرعية والعربية، ثم انتقل إلى إب حيث تولى الإشراف على وقف محمد بن علي الغيثي. جمع تكوينه بين الفقه واللغة ومعرفة تاريخ اليمن وبلدانه وأنسابه، وهي خبرات ستظهر لاحقًا في تعليقاته على كتب التراث وفي تحقيق النصوص الجغرافية والتاريخية.\n\nالإصلاح والسجن\n\nشارك مع زملائه في تأسيس جمعية الإصلاح بمدينة إب سنة 1944 وانتخب رئيسًا لها، ثم اعتقل مع آخرين وأرسل إلى سجن حجة. وبعد إطلاقه عاد إلى إب، لكن إخفاق الثورة الدستورية سنة 1948 أعاده إلى الاعتقال لسنوات أخرى حتى 1955. ثم تولى القضاء في ذي السفال وعمل في محكمة الاستئناف. وتكشف هذه المراحل تقاطع وظيفة العالم والقاضي مع النشاط الإصلاحي في اليمن قبل قيام الجمهورية.\n\nالمسؤوليات بعد الجمهورية\n\nبعد ثورة سبتمبر 1962 عين نائبًا لوزير العدل، ثم وزيرًا للعدل سنة 1963، وتولى الأوقاف سنة 1964 والإعلام خلال 1965 و1966. وعمل أيضًا في رئاسة لجنة التأليف والنشر. لم تقطع المناصب صلته بالبحث؛ إذ تابع قراءة المخطوطات ومناقشة أسماء المواضع والقبائل ومراسلة الباحثين. وكان من أبرز من تواصل معهم العلامة حمد الجاسر، وتوثق مقالات الأخير جانبًا من مكانته العلمية وعلاقاته البحثية.\n\nتحقيق التراث والمؤلفات\n\nحقق الأكوع أكثر من عشرين كتابًا من التراث اليمني، ومن أهم مشروعاته نشر أجزاء من «الإكليل» و«صفة جزيرة العرب» للهمداني، والعمل على «السلوك في طبقات العلماء والملوك» و«العقود اللؤلؤية». وإلى جانب التحقيق كتب عن تجربته في «صفحة من تاريخ اليمن الاجتماعي وقصة حياتي». توفي سنة 1998، وبقيت طبعاته وتعليقاته حاضرة في دراسات تاريخ اليمن الإسلامي وجغرافيته وأنسابه.",
