    "deathYear": 661,
    "shortBio": "حضرموت وزعامة كندة",
    "biographyText": "حضرموت وزعامة كندة\n\nالأشعث بن قيس الكندي، واسمه معديكرب ولقب بالأشعث، من زعماء كندة في حضرموت عند ظهور الإسلام. تنسبه المصادر إلى بيت بني جبلة، وتربط أسرته بحصن النجير. وتختلف التقديرات في ميلاده بين أواخر القرن السادس وبدايات السابع الميلادي، لذلك لم تثبت سنة محددة. تكشف أخباره المبكرة تنافس بيوت كندة وعلاقاتها بقبائل جنوب الجزيرة، ولا تعني زعامته أن جميع بطون كندة اتفقت عليه ملكًا.\n\nالوفادة وحروب الردة\n\nقدم الأشعث في وفد من كندة إلى النبي محمد في أواخر العهد النبوي، وتذكر الروايات سنة 10هـ/631م. عاد بعد ذلك إلى حضرموت، وشارك في الصراع الذي وقع عقب وفاة النبي وارتبط بحروب الردة والامتناع عن الزكاة. أسر ونقل إلى المدينة ثم عاد إلى الجماعة الإسلامية، وتزوج أم فروة أخت أبي بكر. وتعكس هذه المرحلة انتقال زعامة محلية إلى علاقات جديدة مع الدولة الناشئة في المدينة.\n\nالفتوح والولاية\n\nشارك الأشعث في الفتوح بالعراق وفارس، وتذكره الروايات في القادسية وجلولاء ونهاوند، واستقر في الكوفة مع جماعات من كندة. وتولى أذربيجان في عهد عثمان بن عفان، فارتبطت ولايته بإدارة الإقليم والحملات العسكرية فيه. وأصبح من رؤساء القبائل ذوي النفوذ في العراق؛ وهو موقع جمع القيادة العسكرية والمكانة الاجتماعية والمشاركة في إدارة الموارد، ثم أثر في علاقته بالخلفاء خلال سنوات الاضطراب السياسي.\n\nصفين والأسرة والوفاة\n\nكان من قادة جيش علي بن أبي طالب في صفين سنة 37هـ/657م، ومن الشخصيات التي ارتبطت بالدعوة إلى التحكيم. تختلف الأخبار والتقييمات المذهبية في الحكم على مواقفه، لذلك تعرض هنا أعماله العامة دون تبني اتهامات الروايات المتعارضة. توفي بالكوفة سنة 40هـ/661م وصلى عليه الحسن بن علي وفق كتب التراجم. ومن ذريته محمد بن الأشعث، ثم عبد الرحمن بن محمد الذي اشتهر بثورته على الحجاج في العصر الأموي.",
