    "id": "catalog-muhammad-ibrahim-al-wazir",
    "slug": "muhammad-ibrahim-al-wazir",
    "fullName": "محمد بن إبراهيم الوزير",
    "knownFor": "عالم حديث وفقيه يمني دعا إلى الاجتهاد، وصاحب «العواصم والقواصم» و«إيثار الحق على الخلق».",
    "field": "العلم والتعليم",
    "governorateId": "YE29",
    "governorateName": "عمران",
    "era": "تاريخية",
    "birthYear": 1373,
    "deathYear": 1436,
    "shortBio": "النشأة في الظهراوين",
    "biographyText": "النشأة في الظهراوين\n\nولد محمد بن إبراهيم الوزير في قرية الظهراوين بناحية السودة من عمران سنة 775هـ/1373م. نشأ في بيئة علمية زيدية وتلقى علوم الفقه والعربية، ثم توسع في دراسة الحديث وأصول الاستدلال. وعرف في التاريخ العلمي اليمني بوصفه واحدًا من الداعين إلى الاجتهاد والنظر في الأدلة، وهو مسار وضعه في حوار وصراع مع بعض شيوخه ومعاصريه حول حدود التقليد وموقع السنة في الاستنباط.\n\nالمناظرة والاستقلال العلمي\n\nأثار توجه ابن الوزير اعتراضات في محيطه العلمي، وخصه بعض شيوخه بالنقد بعدما كانوا يثنون عليه. ودافع عنه أخوه الهادي بن إبراهيم، وكتب ردًا على منتقدي شعره وآرائه. وتوثق هذه المراسلات والردود خلافًا داخل البيئة العلمية اليمنية، لا انتقالًا بسيطًا بين عناوين مذهبية مغلقة. وقد صاغ ابن الوزير جانبًا من موقفه في الشعر كما في التأليف المطول، وجعل الاحتجاج ومناقشة الأدلة محورًا من محاور عمله.\n\nمشروعه في الحديث والعقيدة\n\nيعد «العواصم والقواصم في الذب عن سنة أبي القاسم» أوسع كتبه، وقد اختصر مادته في «الروض الباسم». وألف «إيثار الحق على الخلق» في مسائل الاعتقاد والمنهج، و«تنقيح الأنظار في علوم الآثار» في مباحث علم الحديث. كما كتب «ترجيح أساليب القرآن على أساليب اليونان»، وفيه موازنة بين طرائق الاستدلال القرآني وبعض مناهج المتكلمين. وتظهر هذه العناوين اتساع مشروعه بين الحديث والجدل والعقيدة.\n\nآثار أخرى ونهاية الحياة\n\nمن آثاره أيضًا «البرهان القاطع في إثبات الصانع» و«قبول البشرى بالتيسير لليسرى»، ورسائل في التفسير وآيات الأحكام. ترك مخطوطات وكتبًا مطبوعة استمر تداولها في الأوساط العلمية اللاحقة، وكان حاضرًا في تاريخ النزعة الاجتهادية باليمن قبل الصنعاني والشوكاني. توفي بصنعاء في وباء الطاعون سنة 840هـ/1436م، وتذكر التراجم أن ابنه عبد الله توفي بالوباء في السنة نفسها.",
