    "id": "catalog-salih-al-maqbali",
    "slug": "salih-al-maqbali",
    "fullName": "صالح بن مهدي المقبلي",
    "knownFor": "عالم يمني موسوعي انتقد التقليد المذهبي، وصاحب «العلم الشامخ» و«المنار» و«الإتحاف لطلبة الكشاف».",
    "field": "العلم والتعليم",
    "governorateId": "YE27",
    "governorateName": "المحويت",
    "era": "تاريخية",
    "birthYear": 1637,
    "deathYear": 1696,
    "shortBio": "الميلاد والدراسة",
    "biographyText": "الميلاد والدراسة\n\nولد صالح بن مهدي المقبلي في قرية المقبل من بلاد المحويت سنة 1047هـ/1637م. نشأ وتعلم في ثلا، ثم اتصل بالبيئات العلمية في صنعاء وكوكبان. شملت دراسته الفقه وأصوله والعربية والحديث والتفسير، وكان تكوينه الأول في الوسط الزيدي. وقد اتسعت اهتماماته إلى مباحث الكلام والتصوف، فصار مشاركًا في علوم متعددة، تتصل بينها عناية واضحة بنقد الحجج وطلب الدليل.\n\nالاجتهاد والمناظرات\n\nعرف المقبلي برفض الالتزام بالتقليد حين يرى أن الدليل يخالفه، ودخل في مناظرات مع علماء صنعاء أدت إلى خلافات شخصية وعلمية. ولم يحصر نقده في مدرسة واحدة؛ فقد ناقش آراء للمعتزلة والأشاعرة وأهل التصوف وبعض المحدثين. وتكشف هذه المواقف عن منهج جدلي مستقل، وإن اختلف الباحثون في تقييم حدته وطريقته. لذلك تعرض آراؤه هنا باعتبارها مواقف مؤلف تاريخي، دون تحويلها إلى حكم على أتباع المذاهب.\n\nالانتقال إلى مكة\n\nرحل المقبلي بأهله إلى مكة سنة 1080هـ/1669م بعد اشتداد الخلاف مع بعض معاصريه. أتاح له الاستقرار في الحجاز مجالًا لمواصلة التأليف والاتصال بعلماء من أقاليم مختلفة، وبقيت كتبه مرتبطة بالأسئلة التي تشكلت في تجربته اليمنية. وتنتمي سيرته إلى تاريخ العلماء الذين عبروا بين اليمن والحرمين، وحملوا معهم نقاشات الفقه والتفسير وأصول الدين إلى مجال علمي أوسع من بيئتهم الأولى.\n\nالمؤلفات والرحيل\n\nمن أشهر آثاره «العلم الشامخ في تفضيل الحق على الآباء والمشايخ»، ويتصل باسمه أيضًا «الأرواح النوافخ». وله «الإتحاف لطلبة الكشاف» في مناقشة تفسير الزمخشري، و«المنار في المختار من جواهر البحر الزخار» في الفقه، و«نجاح الطالب» في أصوله. توفي سنة 1108هـ/1696م. وتتيح مؤلفاته دراسة اتجاه نقد التقليد باليمن في القرن الحادي عشر الهجري وصلاته بالنقاشات العلمية في مكة.",
