    "id": "catalog-abdulwasi-al-wasii",
    "slug": "abdulwasi-al-wasii",
    "fullName": "عبد الواسع الواسعي",
    "knownFor": "مؤرخ وفقيه ورحالة صنعاني عني بنشر التراث اليمني، وله كتب في التاريخ والتقويم والحساب.",
    "field": "التراث والتاريخ",
    "governorateId": "YE13",
    "governorateName": "أمانة العاصمة",
    "era": "معاصرة",
    "birthYear": 1878,
    "deathYear": 1960,
    "shortBio": "صنعاء والتعليم",
    "biographyText": "صنعاء والتعليم\n\nولد عبد الواسع بن يحيى الواسعي في صنعاء سنة 1295هـ/1878م، وتلقى علومه الأولى في المدينة على عدد من علمائها. درس الفقه والحديث والنحو والصرف، وأخذ علم الأوقات عن مختصين به. عكس هذا التكوين تقاليد التعليم في جامع صنعاء وما جاوره، حيث اجتمعت علوم الشريعة والعربية بحساب المواقيت والتقويم، ثم صار الواسعي نفسه من المدرسين في الجامع الكبير والمدرسة العلمية.\n\nالرحلات والاتصال العلمي\n\nرحل الواسعي إلى مكة وأخذ عن علمائها، وزار أقطارًا متعددة من العالم الإسلامي بينها الهند والعراق ومصر والشام. وكان في دمشق عند اندلاع الحرب العالمية الأولى فأقام فيها سنوات قبل عودته إلى اليمن. أتاحت له الرحلات معرفة دور الطباعة والمكتبات والعلماء خارج بلاده، وساعدت في نشاطه اللاحق في نشر الكتب اليمنية والتعريف بتاريخ صنعاء واليمن أمام قراء المشرق العربي.\n\nالتاريخ والتقويم\n\nيعد «تاريخ اليمن المسمى فرجة الهموم والحزن» من أشهر مؤلفاته، كما كتب «البدر المزيل للحزن في فضائل اليمن ومحاسن صنعاء». ولم ينحصر إنتاجه في التاريخ؛ فمن آثاره «زهر الزهور في معرفة الساعات والشهور» الذي أتمه سنة 1316هـ/1899م، و«جداول الأوقات» و«كنز الثقات في معرفة الأوقات» و«نفع الطلاب في علم الحساب». وتكشف هذه الكتب اتصال البحث بالتطبيقات اليومية المتعلقة بالمواقيت والعبادات والتعليم.\n\nالتدريس والآثار الأخرى\n\nترك الواسعي كتبًا ورسائل في الحديث والأسانيد والأصول والنحو، منها «الدر الفريد الجامع لمتفرقات الأسانيد» و«الدراري المضيئات في المعربات والمبنيات». وشارك بالتأليف والطبع في حفظ مادة يمنية لم تكن متاحة لعدد كبير من القراء. توفي بصنعاء سنة 1379هـ/1960م. وتتيح آثاره دراسة صورة اليمن في مطلع القرن العشرين، كما تمثل جانبًا من حياة عالم جمع بين الإقامة للتدريس والرحلة العلمية.",
