    "birthYear": 1927,
    "deathYear": 1991,
    "shortBio": "الشيخ عثمان وبدايات الشعر",
    "biographyText": "الشيخ عثمان وبدايات الشعر\n\nولد محمد سعيد جرادة في مدينة الشيخ عثمان بعدن سنة 1927، وتلقى تعليمه على فقهاء مدينته. بدأ نظم الشعر وهو في الثالثة عشرة، في محيط شهد نمو الصحافة والأندية والمدارس الأهلية. واتصلت تجربته منذ وقت مبكر بالتعليم والقراءة وبالحياة الثقافية في عدن، ثم امتدت إلى الاهتمام بتاريخ الأدب في اليمن كله. وتجمع سيرته بين الشاعر صاحب الديوان والباحث الذي يسعى إلى تعريف القراء بأعلام الفن والثقافة.\n\nالتعليم والإذاعة\n\nعمل جرادة معلمًا نحو خمس وعشرين سنة، ثم عرفه مستمعو إذاعة عدن من خلال عمله الإذاعي. وأتاح المجالان صلة مباشرة بالطلاب والجمهور خارج دائرة النشر الأدبي؛ فحضر الأدب عنده في الصف والميكروفون كما حضر في الكتاب. وكان عضوًا في اتحاد الأدباء والكتاب اليمنيين، وله مساهمات في القصيدة الغنائية إلى جانب القصيدة الفصيحة، وهو تنوع يعكس تداخل التعليم والإعلام والشعر في نشاط أدباء عدن خلال القرن العشرين.\n\nالدواوين الشعرية\n\nصدر له «فردوس القرآن» سنة 1962، ثم «مشاعل الدرب» و«لليمن حبي» سنة 1971، و«وجه صنعاء» في بغداد سنة 1976. وتتيح هذه العناوين تتبع اهتمامه بالموضوع الديني والوطني وبالمدن والهوية اليمنية، مع اختلاف موضوعات القصائد داخل كل ديوان. وجمعت أعماله الشعرية سنة 1988 عن وزارة الثقافة والإعلام في عدن، فصار جزء كبير من إنتاجه متاحًا في طبعة تجمع مراحل متباعدة من التجربة.\n\nالكتابة في تاريخ الثقافة\n\nإلى جانب الشعر ألف جرادة «الثقافة والأدب في اليمن عبر العصور» في جزأين، وكتب «أعلام في الفن والأدب»، كما ترك دراسات وأبحاثًا نشر بعضها في حياته. وتمثل هذه الأعمال اهتمامًا بجمع تاريخ التجارب والأعلام وتقديمه إلى جمهور أوسع، وتكمل صورته معلمًا وإذاعيًا. توفي سنة 1991، وبقيت دواوينه وكتاباته مرجعًا لدراسة جانب من الحياة الأدبية في عدن وصلتها بالتحولات الوطنية والثقافية في اليمن.",
