    "id": "catalog-hussein-salem-basadiq",
    "slug": "hussein-salem-basadiq",
    "fullName": "حسين سالم باصديق",
    "knownFor": "كاتب وقاص ومسرحي من عدن، من مؤسسي اتحاد الأدباء والكتاب اليمنيين وعمل في التعليم والتعاون والبحث الثقافي.",
    "field": "الأدب والشعر",
    "governorateId": "YE24",
    "governorateName": "عدن",
    "era": "معاصرة",
    "birthYear": 1928,
    "deathYear": 1996,
    "shortBio": "عدن والدراسة",
    "biographyText": "عدن والدراسة\n\nولد حسين سالم باصديق في عدن في 9 ديسمبر 1928، وتعلم فيها حتى نال شهادة كامبريدج العليا سنة 1948. بدأ الكتابة الأدبية في صحافة المدينة في الأربعينيات، ثم تابع تأهيله المهني وحصل على دبلوم في الاقتصاد التعاوني من جامعة نوتنغهام سنة 1962. ويكشف هذا المسار اتصال التعليم المحلي في عدن بالتأهيل الخارجي، كما يوضح تعدد اهتماماته بين الأدب والإدارة والعمل الاجتماعي.\n\nالمهن والعمل العام\n\nعمل باصديق في الأرصاد الجوية بين 1948 و1950، ثم مدرسًا في مدرسة بازرعة خلال 1951–1956. وعمل في الشؤون الاجتماعية وقضايا الأطفال، ثم في التعاون والتسويق حتى بلغ موقع المدير العام. وخلال 1968–1971 شارك في هيئة خبراء التعاون العرب بجامعة الدول العربية. ولاحقًا عمل مترجمًا وفي سكرتارية مجلس الوزراء، ثم في المركز اليمني للأبحاث الثقافية والآثار والمتاحف بعدن ودائرة التأليف والترجمة والنشر.\n\nالمسرح والإذاعة والتلفزيون\n\nبدأ باصديق كتابة المسرحيات مبكرًا، ومن أعماله «بائع البطيخ» سنة 1956. وامتد إنتاجه إلى النص التلفزيوني، فقدم مسلسل «حب خلف الآفاق البعيدة» سنة 1976، وإلى الإذاعة بمسلسل «الصفقة الجديدة» سنة 1983. وتعد هذه المشاركات جزءًا من انتقال الأدب في عدن من الصحيفة والكتاب إلى وسائط الأداء والبث. وكتب في القصة والرواية والمسرحية، ولم يحصر نشاطه في جنس أدبي واحد.\n\nالمؤلفات والمؤسسات الثقافية\n\nمن عناوينه «طريق الغيوم» و«عذراء الجبل» و«أشعة حريرية» و«الجرة الفضية» و«الإبحار على متن حسناء». وظهر كتابه «الإبحار في عينيها» سنة 1996 في أواخر حياته. وكان عضوًا مؤسسًا في اتحاد الأدباء والكتاب اليمنيين، وله مشاركة في الحركة الكشفية وإدارة نادي التلال الرياضي. توفي سنة 1996، وتبقى سيرته مرتبطة بالمؤسسات التعليمية والاجتماعية والثقافية التي تشكلت حول مدينة عدن.",
    "imageUrl": "",
