    "id": "catalog-abdullah-mohammed-al-hibshi",
    "slug": "abdullah-mohammed-al-hibshi",
    "fullName": "عبد الله محمد الحبشي",
    "knownFor": "باحث ومحقق يمني في المخطوطات والببليوغرافيا، صاحب «مصادر الفكر الإسلامي في اليمن» و«جامع الشروح والحواشي».",
    "field": "التراث والتاريخ",
    "governorateId": "YE19",
    "governorateName": "حضرموت",
    "era": "معاصرة",
    "birthYear": 1949,
    "deathYear": null,
    "shortBio": "حضرموت وبدايات التكوين",
    "biographyText": "حضرموت وبدايات التكوين\n\nولد عبد الله محمد الحبشي في حضرموت سنة 1949، وتلقى دروسه الأولى على علماء أسرته ومحيطه. انتقل إلى عدن ثم صنعاء، وأقام فيها سنوات قبل انتقاله للعمل في أبوظبي. اتجه في مسيرته إلى التاريخ والمخطوطات والفهارس، فجمع بين قراءة نصوص التراث وتحقيقها وبين وصف ما ألفه العلماء وتحديد مصادره. ويختلف اختصاصه عن مجرد سرد الوقائع؛ إذ يهتم كذلك بالأدوات التي تساعد الباحث على الوصول إلى الكتب وأصحابها.\n\nالفهرسة والببليوغرافيا\n\nمن أشهر أعمال الحبشي «مصادر الفكر الإسلامي في اليمن»، الذي يعرف بالتأليف اليمني ومادته العلمية. وأعد «جامع الشروح والحواشي» و«معجم الموضوعات المطروقة في التأليف الإسلامي وبيان ما ألف فيها»، وهي أعمال تتبع العلاقات بين المتون وشروحها وما كتب في الموضوعات المختلفة. كما ألف «فهرس مخطوطات بعض المكتبات الخاصة في اليمن»، مساهمًا في التعريف بمادة موزعة بين خزائن قد لا تتاح للجمهور على نطاق واسع.\n\nتحقيق التاريخ اليمني\n\nحقق الحبشي عددًا كبيرًا من النصوص في تاريخ اليمن وحضرموت وزبيد وصنعاء. ومن مشروعاته نصوص للكندي والخزرجي وابن الديبع وغيرهم، مثل «السلوك في طبقات العلماء والملوك» و«العقود اللؤلؤية» و«الفضل المزيد على بغية المستفيد». ويشمل عمل التحقيق قراءة النسخ ومقابلة النصوص والتعليق والتعريف بالمؤلف، وهو ما نقل جانبًا من المادة التاريخية من التداول المخطوط إلى الطباعة والاستعمال البحثي.\n\nمجالات أخرى في التأليف\n\nتضم قائمة آثاره «معجم النساء اليمانيات» و«الرحالة اليمنيون رحلاتهم شرقًا وغربًا» و«حياة الأدب في اليمن في عصر بني رسول» و«معجم البلدان اليمنية». وتعكس هذه الأعمال اهتمامًا بأسماء قد تغيب عن السرد السياسي، وبالحركة العلمية والجغرافيا والرحلة. كما كتب تصحيحات وتنبيهات على أخطاء كتب التراجم والفهارس، فجمع بين إضافة مواد جديدة ومراجعة أدوات البحث المتداولة في دراسة التراث.",
    "imageUrl": "",
    "imageCredit": "",
    "imageSourceUrl": "",
    "imageKind": "portrait",
