    "id": "catalog-abdulrahman-tayyib-baakar",
    "slug": "abdulrahman-tayyib-baakar",
    "fullName": "عبد الرحمن طيب بعكر",
    "knownFor": "شاعر وناقد ومؤرخ من حيس، كتب عن شعراء اليمن وأعلامه وحقق ديوان عبد الرحمن الآنسي.",
    "field": "التراث والتاريخ",
    "governorateId": "YE18",
    "governorateName": "الحديدة",
    "era": "معاصرة",
    "birthYear": 1944,
    "deathYear": 2007,
    "shortBio": "حيس والتعليم",
    "biographyText": "حيس والتعليم\n\nولد عبد الرحمن طيب بعكر الحضرمي في حيس بمحافظة الحديدة سنة 1944، في أسرة ذات أصول حضرمية استقرت بتهامة. أخذ عن والده ومشايخ بلدته مبادئ العربية والحساب والفقه الشافعي، ثم انتقل إلى صنعاء فدرس في المدرسة الثانوية والجامع الكبير، ولازم أحمد قاسم دهمش. واتصل بعلماء وشعراء منهم عبد الله محمد عطية ودبوان العديني، فجمع تعليمه بين العلوم الدينية والاهتمام المبكر بالشعر والنقد.\n\nالعمل والتحول إلى التأليف\n\nعاد بعكر إلى حيس وعمل سكرتيرًا لمركز الناحية ثم قائمًا بأعمال المديرية سنة 1966، واستمر في العمل حتى أصيب بفقد البصر. لم يوقف ذلك نشاطه الأدبي والبحثي؛ فاتجه إلى التأليف وجمع أخبار الأعلام وقراءة الشعر ومناقشته. ومن باكورة كتبه «ملامح اليمن والضمادات المطلوبة» سنة 1984، ثم ديوان «أجراس» سنة 1985. وقد اقترنت تجربته بالمثابرة في البحث رغم العائق البصري وبالحضور في المؤسسات الأدبية اليمنية.\n\nالنقد والشعر والتحقيق\n\nتناول بعكر شعر عبد الله البردوني وعبد الله محمد عطية والفضول وحسن الشرفي في كتاباته النقدية. وحقق «الأنموذج الفائق للنظم الرائق» لعبد الرحمن الآنسي، وأفرد للآنسي دراسة بعنوان «شاعر التوحيد والعدل والجمال». كما كتب «كيف غنت تهامة» و«عناقيد أدب وفن» و«جمرات نثرية»، وجمع بين تحليل القصيدة والتعريف بالشاعر وبيئته. وله دواوين منها «أجراس» و«سجادة الخضر».\n\nالتاريخ والتراجم والرحيل\n\nألف «كواكب يمنية في سماء الإسلام» و«نظرات في التاريخ العام لليمن»، وكتب عن أحمد محمد نعمان ومحمد محمود الزبيري ومحمد بن إسماعيل الأمير. وتعكس هذه الأعمال اهتمامًا بربط التاريخ الوطني بالتراجم والفكر والأدب. توفي في محافظة الحديدة في 18 يناير 2007، ودفن في حيس. وبقيت كتبه حاضرة في دراسة شعراء تهامة واليمن وفي توثيق سير شخصيات من الحركة العلمية والثقافية والوطنية.",
