    "deathYear": 2022,
    "shortBio": "الأسرة والتكوين الأول",
    "biographyText": "الأسرة والتكوين الأول\n\nأبو بكر عبد الرحمن السقاف مفكر يمني ارتبط بالوهط في محافظة لحج وبالتعليم الفلسفي في جامعة صنعاء. ولد في أسرة مهاجرة، وتورد مصادر مولده بإثيوبيا في منتصف الثلاثينيات قبل عودته إلى موطن والده وهو طفل. درس في المدرسة الجعفرية بالوهط ثم المحسنية بالحوطة. وتختلف التراجم بين 1934 و1935 وفي ضبط مكان الميلاد، فتركت هذه السيرة سنة الميلاد فارغة واعتمدت المراحل التعليمية الأوضح توثيقًا.\n\nالقاهرة وموسكو والجامعة\n\nرشحه نادي الشباب اللحجي في بعثة تعليمية إلى القاهرة سنة 1954، وشارك في النشاط الطلابي اليمني. وانتخب سنة 1956 سكرتيرًا أول للمؤتمر العام للطلاب اليمنيين بمصر. ثم ابتعث إلى موسكو سنة 1959 ودرس الفلسفة حتى نال الدكتوراه، وعاد إلى اليمن سنة 1974 للتدريس في جامعة صنعاء. وقد امتدت خبرته بين بيئة المدرسة الأهلية والبعثة الطلابية والتعليم الفلسفي، وهو ما أعطى كتاباته أفقًا مقارنًا في السياسة والفكر.\n\nالفلسفة والحريات\n\nعُرف السقاف بكتاباته في الحريات وحقوق الإنسان ونقد الاستبداد وبالحضور في الجدل العام إلى جانب التدريس. ولم يقتصر أثره على المؤلفات المنفصلة؛ فقد نشر مقالات ودراسات تناولت الدولة والمواطنة وعلاقة المجتمع بالسلطة. ومن نصوصه مقال «الفريضة الغائبة: الدولة المدنية» سنة 2007، الذي يبرز موقع فكرة الدولة المدنية في اهتمامه. وقد تعرض لاعتداءات واختطاف في فترات ارتبطت بمواقفه المنتقدة للسلطات بحسب الدراسات التي تناولت سيرته.\n\nالسنوات الأخيرة والإرث\n\nغادر السقاف اليمن مع زوجته إلى روسيا في أبريل 2015 على متن رحلة إجلاء بعد اندلاع الحرب، ثم توفي في موسكو في ديسمبر 2022. وتناولت دراسات لاحقة دوره في التعليم الجامعي والتفكير النقدي والدفاع عن الفئات المقهورة. وتحفظ المقالات وشهادات معاصريه جانبًا أساسيًا من سيرته؛ إذ لم يكن حضوره قائمًا على المنصب السياسي، وإنما على التدريس والكتابة والمشاركة في النقاش حول الحقوق والعدالة والدولة.",
