    "id": "catalog-abdullah-hadi-subait",
    "slug": "abdullah-hadi-subait",
    "fullName": "عبد الله هادي سبيت",
    "knownFor": "شاعر وملحن لحجي من رواد الأغنية اليمنية، صاحب «الدموع الضاحكة» و«الفلاح والأرض» و«يا ظالم لك يوم».",
    "field": "الأدب والشعر",
    "governorateId": "YE25",
    "governorateName": "لحج",
    "era": "معاصرة",
    "birthYear": null,
    "deathYear": 2007,
    "shortBio": "الحوطة والتعليم",
    "biographyText": "الحوطة والتعليم\n\nعبد الله هادي سبيت شاعر وملحن من مدينة الحوطة بلحج، نشأ فيها وتلقى تعليمه حتى المرحلة الإعدادية التي كانت أعلى مراحل التعليم المتاحة في محيطه آنذاك. تختلف المراجع في سنة مولده بين 1918 و1921، ولذلك لا تعتمد هذه السيرة سنة قطعية. عمل مدرسًا ثم في دائرة المعارف، وتولى مسؤوليات في سلطنة لحج. وارتبط تكوينه بالثقافة اللحجية التي جمعت الشعر الشعبي والغناء والمجالس الأدبية.\n\nالشعر والتلحين والعمل الوطني\n\nبدأت موهبته في صياغة الألحان بالظهور في الأربعينيات، وجمع بين كتابة النص وتلحينه، وهو جانب لا يظهر دائمًا حين تعرف أغانيه بأصوات مطربين آخرين. وكان من المشاركين في الحركة المناهضة للاستعمار البريطاني، وانتقل بسبب نشاطه من الجنوب إلى شمال اليمن ثم إلى مصر. وتحمل أعماله موضوعات وجدانية واجتماعية ووطنية، فأفادت أغنيته من اللهجة المحلية ومن قرب الصورة الشعرية إلى الحياة اليومية.\n\nالدواوين والمسرح\n\nصدر «الدموع الضاحكة» سنة 1953، وهو من أبرز دواوينه العامية المغناة. وله «مع الفجر» و«الفلاح والأرض» و«أناشيد الحياة» و«رجوع إلى الله»، مع اختلاف بعض المراجع في تأريخ طبعات هذه الكتب. وتمثل «الفلاح والأرض» تجربة شعرية تتصل بالريف والعمل، بينما تظهر دواوين أخرى كتابته بالفصحى إلى جانب الحميني. كما شارك بنصوص مسرحية ومواد للإذاعة والتلفزيون، ما وسع حضوره خارج إطار الأغنية.\n\nالأغاني والرحيل\n\nمن العناوين المرتبطة به «يا ظالم لك يوم» و«زمان الخوف ولى وراح» و«القمر كم بيذكرني جبينك» و«سألتني عن هوايا»، وقد تداولها مستمعون في اليمن وخارجه. توفي في أبريل 2007، وتناولت الصحافة تجربته شاعرًا وملحنًا وصاحب حضور وطني. وتوضح سيرته كيف أسهم أدباء لحج في بناء الأغنية اليمنية الحديثة، وكيف انتقل النص المحلي إلى جمهور أوسع عبر الأصوات والإذاعة والتسجيلات.",
