    "id": "catalog-abdulmajid-al-zindani",
    "slug": "abdulmajid-al-zindani",
    "fullName": "عبد المجيد الزنداني",
    "knownFor": "داعية وسياسي يمني أسس جامعة الإيمان وكان من قيادات التجمع اليمني للإصلاح وعضوًا بمجلس الرئاسة.",
    "field": "العلم والتعليم",
    "governorateId": "YE11",
    "governorateName": "إب",
    "era": "معاصرة",
    "birthYear": null,
    "deathYear": 2024,
    "shortBio": "النشأة والتعليم",
    "biographyText": "النشأة والتعليم\n\nعبد المجيد بن عزيز الزنداني داعية وسياسي يمني ولد في قرية الظهبي بمديرية الشعر في إب، وتعود نسبة أسرته إلى زندان بأرحب. تختلف المراجع في مولده، وتشيع سنة 1942 مقابل تواريخ أخرى؛ لذلك لا تثبت هذه السيرة سنة واحدة. درس في الكتّاب ثم في عدن، والتحق بدراسة الصيدلة في مصر دون إكمالها، واتجه إلى العلوم الشرعية. واتصل هناك بطلاب وشخصيات يمنية منهم محمد محمود الزبيري.\n\nالدعوة والتعليم والمؤسسات\n\nبعد عودته إلى اليمن شارك في نشاط ديني وتعليمي، وعمل في الإرشاد والمعارف. واهتم بربط تفسير النصوص الدينية بما يسمى الإعجاز العلمي في القرآن والسنة، وأسهم في تأسيس الهيئة المعنية به في مكة. وفي سنة 1993 أسس جامعة الإيمان في صنعاء، التي تخصصت في التعليم الديني. ومن كتبه «توحيد الخالق» و«علم الإيمان» و«طريق الإيمان»، وهي أعمال دعوية تعرض منهجه في الاستدلال والتربية الدينية.\n\nالسياسة والجدل العام\n\nشارك الزنداني في تأسيس التجمع اليمني للإصلاح وتولى رئاسة مجلس شوراه، وانتخب عضوًا في مجلس الرئاسة سنة 1993. وعرف بمواقفه السياسية والدينية وبجدل واسع حول بعض أطروحاته. وفي 24 فبراير 2004 أعلنت وزارة الخزانة الأمريكية إدراجه على قائمة العقوبات متهمة إياه بدعم القاعدة؛ ويعرض ذلك هنا بوصفه قرارًا رسميًا أمريكيًا ذا أثر على سيرته السياسية، مع نسبة الاتهام إلى الجهة التي أصدرته دون تحويله إلى رواية غير منسوبة.\n\nالسنوات الأخيرة والوفاة\n\nأيد احتجاجات الشباب اليمنية سنة 2011، ثم غادر البلاد في سياق الحرب سنة 2015 وأقام في السعودية قبل انتقاله إلى تركيا سنة 2020. توفي في إسطنبول في 22 أبريل 2024، ودفن فيها في اليوم التالي. ولتقييم مسيرته يجدر النظر معًا إلى مؤسساته التعليمية ودوره الحزبي ومواقفه الدينية والقرارات الدولية المرتبطة باسمه، فهي جوانب متعددة صنعت حضوره المختلف عليه في المجال العام اليمني.",
