    "id": "catalog-mohammed-salem-al-bayhani",
    "slug": "mohammed-salem-al-bayhani",
    "fullName": "محمد بن سالم البيحاني",
    "knownFor": "عالم وأديب وتربوي يمني من بيحان، أسس مؤسسات تعليمية في عدن وكتب «إصلاح المجتمع» وشعرًا تعليميًا.",
    "field": "العلم والتعليم",
    "governorateId": "YE21",
    "governorateName": "شبوة",
    "era": "معاصرة",
    "birthYear": 1908,
    "deathYear": 1972,
    "shortBio": "بيحان والتكوين العلمي",
    "biographyText": "بيحان والتكوين العلمي\n\nولد محمد بن سالم الكدادي البيحاني في منطقة القصاب ببيحان بمحافظة شبوة سنة 1908، ونشأ في أسرة اهتمت بالعلم. أخذ القرآن ومبادئ العلوم عن والده سالم بن حسين، وفقد بصره في طفولته، ثم واصل التعلم على علماء بيحان. وانتقل إلى تريم بحضرموت سنة 1916 فدرس العلوم الشرعية والعربية، ثم اتصل بعلماء عدن. وتوضح هذه المراحل امتداد تكوينه بين مراكز علمية يمنية متعددة قبل رحلته إلى مصر.\n\nالأزهر والعمل في عدن\n\nالتحق البيحاني بالأزهر في القاهرة ونال الشهادتين الأهلية والعالمية، ثم عاد إلى اليمن وعمل بالتدريس والإفتاء. استقر في كريتر بعدن واشتهر بإمامة جامع العسقلاني وخطابته، حيث أقام دروسًا في الحديث والتفسير والفقه والعربية. ومع اتساع نشاطه ساهم في الجمعية الإسلامية للتربية والتعليم سنة 1950، وأسس المعهد العلمي الإسلامي سنة 1957، فجمع التعليم في حلقات المسجد ببناء مؤسسة تعليمية منظمة.\n\nالتأليف والشعر التعليمي\n\nخلف البيحاني كتبًا تتناول الإصلاح الديني والاجتماعي والتربية، منها «إصلاح المجتمع» و«تربية البنين» و«أستاذ المرأة» و«كيف نعبد الله؟». وكتب «أشعة الأنوار على مرويات الأخبار» الذي طبع سنة 1964، وله «رباعيات البيحاني» و«العطر اليماني من أشعار البيحاني». واتصل شعره بالتعليم والموعظة وتناول قضايا المجتمع، إلى جانب اهتمامه بالخطابة؛ فكانت القصيدة وسيلة للإرشاد مثلما كانت جنسًا أدبيًا.\n\nالانتقال إلى تعز وحفظ الآثار\n\nتعرض نشاط البيحاني لمضايقات في مرحلة التحولات السياسية بعد استقلال الجنوب، ثم انتقل من عدن إلى تعز في أواخر حياته. توفي في تعز في فبراير 1972 ودفن فيها، مع اختلاف بعض الأخبار في ضبط يوم الوفاة. استمرت مؤسسات وتلاميذ في العناية بإرثه، وأعلنت دار جامعة عدن سنة 2014 إصدار «بغية القاصد من أحسن القصائد» ضمن سلسلة الكتاب الجامعي، وهو جانب من إعادة تقديم شعره للأجيال اللاحقة.",
