    "deathYear": 1956,
    "shortBio": "سيئون والأسرة العلمية",
    "biographyText": "سيئون والأسرة العلمية\n\nنشأ عبد الرحمن بن عبيد الله السقاف في سيئون بحضرموت في أسرة علمية، وولد في أواخر القرن التاسع عشر؛ إذ تختلف المراجع بين 1882 و1883، وتقابلها روايتا 1299 و1300هـ. حفظ القرآن وأخذ عن والده وعن علماء حضرموت علوم الفقه والعربية والحديث، ثم أجازه شيوخه بالتدريس والإفتاء. وعرف لاحقًا بمفتي الديار الحضرمية، وجمع بين المعرفة الشرعية والذائقة الأدبية والاهتمام بتفاصيل تاريخ المدن والأسر.\n\nالفقه والتدريس والرحلة\n\nتصدر السقاف للتدريس والإفتاء بمسجد طه بن عمر في سيئون، وأخذ عنه طلاب أصبح عدد منهم من علماء حضرموت وخارجها. ورحل إلى الحجاز وإندونيسيا واتصل بعلماء وشخصيات عامة. وتدخل في الشؤون الاجتماعية ومحاولات الإصلاح وحل الخلافات، وكانت له صلات بحكام حضرموت وإمام اليمن يحيى حميد الدين. وتظهر هذه المشاركات موقع العالم في الوساطة والمراسلات والسياسة المحلية في النصف الأول من القرن العشرين.\n\nتاريخ حضرموت وبلدانها\n\nيعد «إدام القوت في ذكر بلدان حضرموت» أشهر كتبه عند الباحثين في التاريخ المحلي، وهو معجم يجمع الجغرافيا بالتراجم والأدب والأحوال الاجتماعية. وله أيضًا «بضائع التابوت في نتف من تاريخ حضرموت»، وفيه مادة تاريخية وأدبية واسعة. وتكتسب هذه الأعمال قيمة من معرفة المؤلف بالأسر والمواضع وأخبار عصره، مع ضرورة قراءة مواقفه وتعليقاته بوصفها وجهة نظر مؤلف مشارك في المجتمع الذي يصفه.\n\nالأدب والآثار والوفاة\n\nمن آثاره «العود الهندي عن أمالي في ديوان الكندي»، وهي مجالس في شعر المتنبي تجمع الشرح بالمناقشة الأدبية. وكتب الشعر والخطب والحواشي الفقهية، ومنها «صوب الركام في شؤون القضاء والأحكام»، وترك ديوانًا يعرف بديوان ابن عبيد الله. توفي في سيئون سنة 1375هـ/1956م، وامتدت مجالس تأبينه إلى مجتمعات حضرمية في المهجر. وتبقى مؤلفاته من المداخل المهمة لدراسة ذاكرة حضرموت العلمية والأدبية والاجتماعية.",
    "imageUrl": "",
    "imageCredit": "",
    "imageSourceUrl": "",
